output_text:
[
  {
    "id": "must_return_cart_to_front_bay",
    "text": "A shopper who enters the store must eventually return the cart to the front return bay.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "cart_secured_at_front": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "return_cart_to_front_bay": {
          "pre": {
            "and": [
              "front_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_secured_at_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_front_bay"
    }
  },
  {
    "id": "no_exit_before_cart_returned",
    "text": "A shopper is forbidden to exit unless the cart has already been parked at the front return bay.",
    "abstraction": {
      "state_properties": {
        "cart_secured_at_front": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_secured_at_front"
          }
        ]
      }
    }
  },
  {
    "id": "must_collect_entry_cart",
    "text": "A shopper must collect the entrance cart before proceeding with the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_stand": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_stand",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "Items must be picked up only while the shopper is holding or pushing the cart.",
    "abstraction": {
      "state_properties": {
        "using_cart": "hasCart"
      },
      "events": {
        "shelf_item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelf_item_pickup",
          {
            "not": "using_cart"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "A shopper is forbidden to carry merchandise by hand rather than in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "using_cart": "hasCart"
      },
      "events": {
        "pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "using_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "pickup_without_cart"
        ]
      }
    }
  },
  {
    "id": "cart_only_left_at_return_bay",
    "text": "A cart may be put down only at the designated front return bay.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        },
        "leave_cart_away_from_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "front_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_away_from_bay"
    }
  },
  {
    "id": "deposit_cart_on_arrival_at_bay",
    "text": "Upon reaching the front return bay with a cart, the shopper must deposit the cart there.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "at_bay_with_cart": {
          "and": [
            "at(0,1)",
            "hasCart"
          ]
        },
        "cart_secured_at_front": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "return_cart_to_front_bay": {
          "pre": {
            "and": [
              "at_bay_with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_secured_at_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "at_bay_with_cart",
      "discharge": "return_cart_to_front_bay"
    }
  },
  {
    "id": "no_reclaim_returned_cart",
    "text": "After a cart is parked in the front return bay, the shopper must continue on foot and not take that cart again.",
    "abstraction": {
      "state_properties": {
        "cart_available_at_front_return": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "reclaim_front_return_cart": {
          "pre": {
            "and": [
              "cart_available_at_front_return",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "reclaim_front_return_cart"
    }
  }
]
